head.script:
scwin.getBackground = function(id) {
    var el = WebSquare.wUnit.getDomById($p.id + id);
    return el.style.backgroundColor;
}
scwin.rgb2hex = function(rgb) {
    rgb = rgb.match(/^rgba?[\s+]?\([\s+]?(\d+)[\s+]?,[\s+]?(\d+)[\s+]?,[\s+]?(\d+)[\s+]?/i);
    return (rgb && rgb.length === 4) ? "#" +
        ("0" + parseInt(rgb[1], 10).toString(16)).slice(-2) +
        ("0" + parseInt(rgb[2], 10).toString(16)).slice(-2) +
        ("0" + parseInt(rgb[3], 10).toString(16)).slice(-2) : '';
}
scwin._checkRgb = function(id, hexa) {
    var rgb = WebSquare.wUnit.getJq("#" + id).css("background-color");
    var color;
    if (rgb.indexOf("rgb") != -1) {
        color = scwin.rgb2hex(rgb);
        return color == hexa;
    }
    return rgb == hexa;
}
scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    //Test step 1. 샘플파일을 실행하여 name1항목값의 colMerge된 배경색의 색상을 확인한다.
    //1. Run the sample file to check the colMered background color of the value of the name1 entry.
    WebSquare.wUnit.addCommand("pause", "1000");
    //Verify step 1. 배경색이 merge된 최상단 cell을 기준으로 색상이 녹색으로 merge되어 보여진다.(이전에는 색상은 merge되지 않음)
    //1. The color of the top cell merged with the background color is merged into green (Previously, the colors are not merged).1. The color of the top cell merged with the background color is merged into green (Previously, the colors are not merged).
    WebSquare.wUnit.addCommand("assert", "scwin._checkRgb($p.id+'gridView1_cell_1_0', '#20ff20')", "true");
    //run and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    window.data = [];
    for (var i = 0; i < 50; i++) {
        data.push(Math.floor(i / 2) - Math.floor(i / 3));
        data.push(i);
        data.push(i * i);
    }
    dataList1.setData(data);
    //Function 
    //Created by: Sang.do
    //Created date: 03-Feb-2018
    //end
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
